//https://leetcode.com/problems/count-alternating-subarrays/
class Solution {
public:
    long long countAlternatingSubarrays(vector<int>& nums) {
        long long res = 0;
        int alter = 0;
        for(int i=0; i<nums.size(); i++){
            if(i != 0 && nums[i] != nums[i-1]){
                alter++;
            }else{
                alter = 1;
            }
            res += alter;
        }
        return res;
    }
};
